#include "files.h"
#include "heap.h"
struct file files[FILE_MAX_COUNT];uint32_t file_count;static void cp(uint8_t*d,const uint8_t*s,uint32_t n){for(uint32_t i=0;i<n;++i)d[i]=s[i];}static void cpf(struct file*d,const struct file*s){cp(d->path,s->path,s->path_length);d->path_length=s->path_length;d->content=s->content;d->content_length=s->content_length;d->content_capacity=s->content_capacity;d->attributes=s->attributes;}static int eq(const uint8_t*a,uint32_t n,const uint8_t*b,uint32_t m){if(n!=m)return 0;for(uint32_t i=0;i<n;++i)if(a[i]!=b[i])return 0;return 1;}static int cmp(const uint8_t*a,uint32_t n,const uint8_t*b,uint32_t m){uint32_t z=n<m?n:m;for(uint32_t i=0;i<z;++i){if(a[i]<b[i])return-1;if(a[i]>b[i])return 1;}return n<m?-1:n>m;}static int reserve(struct file*f,uint32_t n){if(n<=f->content_capacity)return 1;uint32_t z=f->content_capacity;if(z<256)z=256;while(z<n){if(z>UINT32_MAX/2){z=n;break;}z*=2;}uint8_t*p=heap_alloc(z);if(!p)return 0;cp(p,f->content,f->content_length);if(f->content&&!heap_free(f->content)){(void)heap_free(p);return 0;}f->content=p;f->content_capacity=z;return 1;}static int create(const uint8_t*p,uint32_t n,const uint8_t*d,uint32_t z){if(!n||n>FILE_MAX_PATH_LENGTH||file_count>=FILE_MAX_COUNT)return 0;uint32_t at=0;while(at<file_count){int q=cmp(files[at].path,files[at].path_length,p,n);if(!q)return 0;if(q>0)break;++at;}struct file f;f.path_length=(uint16_t)n;f.content=0;f.content_length=f.content_capacity=f.attributes=0;cp(f.path,p,n);if(z){if(!reserve(&f,z))return 0;cp(f.content,d,z);f.content_length=z;}for(uint32_t i=file_count;i>at;--i)cpf(&files[i],&files[i-1]);cpf(&files[at],&f);++file_count;return 1;}static void discard(void){while(file_count){--file_count;if(files[file_count].content)(void)heap_free(files[file_count].content);}}int files_init(void){file_count=0;if(initial_file_count>FILE_MAX_COUNT)return 0;for(uint32_t i=0;i<initial_file_count;++i){const struct embedded_file*f=&initial_files[i];uintptr_t n=(uintptr_t)f->end-(uintptr_t)f->data;if(n>UINT32_MAX||!create(f->path,f->path_length,f->data,(uint32_t)n)){discard();return 0;}}return 1;}uint32_t file_size(const struct file*f){return f->content_length;}const uint8_t*file_content(const struct file*f){return f->content;}uint32_t file_attributes(const struct file*f){return f->attributes;}struct file*file_find(const uint8_t*p,uint32_t n){for(uint32_t i=0;i<file_count;++i)if(eq(p,n,files[i].path,files[i].path_length))return&files[i];return 0;}int file_path_has_prefix(const struct file*f,const uint8_t*p,uint32_t n){return n<=f->path_length&&eq(f->path,n,p,n);}static int resize(struct file*f,uint32_t n,int zero){uint32_t old=f->content_length;if(n==old)return 1;if(!n){if(f->content&&!heap_free(f->content))return 0;f->content=0;f->content_length=f->content_capacity=0;return 1;}if(!reserve(f,n))return 0;if(zero&&n>old)for(uint32_t i=old;i<n;++i)f->content[i]=0;f->content_length=n;return 1;}int file_write_span(const uint8_t*p,uint32_t n,uint32_t off,uint32_t z,uint8_t**out){struct file*f=file_find(p,n);if(!f){if(off||!create(p,n,0,0))return 0;f=file_find(p,n);}if(!f||(f->attributes&FILE_ATTRIBUTE_IMMUTABLE)||off>f->content_length||z>UINT32_MAX-off)return 0;if(z&&off+z>f->content_length&&!resize(f,off+z,0))return 0;*out=z?f->content+off:0;return 1;}int file_write(const uint8_t*p,uint32_t n,uint32_t off,const uint8_t*d,uint32_t z){uint8_t*q;if(!file_write_span(p,n,off,z,&q))return 0;cp(q,d,z);return 1;}int file_truncate(const uint8_t*p,uint32_t n,uint32_t z){struct file*f=file_find(p,n);return f&&!(f->attributes&FILE_ATTRIBUTE_IMMUTABLE)&&resize(f,z,1);}int file_remove(const uint8_t*p,uint32_t n){struct file*f=file_find(p,n);if(!f||(f->attributes&FILE_ATTRIBUTE_IMMUTABLE))return 0;uint32_t at=(uint32_t)(f-files);if(f->content&&!heap_free(f->content))return 0;for(uint32_t i=at;i+1<file_count;++i)cpf(&files[i],&files[i+1]);--file_count;return 1;}int file_seal(const uint8_t*p,uint32_t n){struct file*f=file_find(p,n);if(!f)return 0;f->attributes|=FILE_ATTRIBUTE_IMMUTABLE;return 1;}
